{"type":"item.completed","item":{"id":"item_1","type":"agent_message","text":"{\"tool\":\"sql_query\",\"arguments\":{\"company_name\":\"CLOSE_fin_06\",\"table_name\":\"ledger\",\"query\":\"WITH eligible AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY kind, event_key ORDER BY revision DESC) AS rn FROM ledger WHERE date(business_date) <= date('2026-10-23') AND datetime(recorded_at) <= datetime('2026-10-24 12:00:00')), active AS (SELECT * FROM eligible WHERE rn = 1 AND status <> 'void'), invoices AS (SELECT * FROM active WHERE kind = 'invoice' AND vendor = 'BLUE' AND date(due_date) <= date('2026-10-30')), terms_ranked AS (SELECT i.event_key AS inv_key, t.discount_until, t.discount_bps, ROW_NUMBER() OVER (PARTITION BY i.event_key ORDER BY date(t.business_date) DESC) AS rn FROM invoices i JOIN active t ON t.kind = 'terms' AND t.terms_code = i.terms_code AND date(t.business_date) <= date(i.business_date)), fx_ranked AS (SELECT i.event_key AS inv_key, f.fx_num, f.fx_den, ROW_NUMBER() OVER (PARTITION BY i.event_key ORDER BY date(f.business_date) DESC) AS rn FROM invoices i JOIN active f ON f.kind = 'fx' AND f.currency = i.currency AND date(f.business_date) <= date(i.business_date)), reductions AS (SELECT i.event_key, i.amount_minor, i.currency, i.discount_until, i.discount_bps, COALESCE(SUM(CASE WHEN p.kind = 'payment' THEN p.amount_minor ELSE 0 END),0) AS paid, COALESCE(SUM(CASE WHEN p.kind = 'credit' THEN p.amount_minor ELSE 0 END),0) AS credited, COALESCE(SUM(CASE WHEN p.kind = 'hold' AND p.status NOT IN ('release','void') THEN p.amount_minor ELSE 0 END),0) AS held FROM invoices i LEFT JOIN active p ON p.invoice_id = i.event_key AND p.kind IN ('payment','credit','hold') GROUP BY i.event_key), amounts AS (SELECT r.*, tr.discount_bps AS terms_bps, tr.discount_until AS terms_until, fr.fx_num, fr.fx_den FROM reductions r JOIN terms_ranked tr ON tr.inv_key = r.event_key AND tr.rn = 1 JOIN fx_ranked fr ON fr.inv_key = r.event_key AND fr.rn = 1), final_num AS (SELECT MAX(0, MAX(0, amount_minor-paid-credited)-held) * CASE WHEN date('2026-10-23') <= date(terms_until) THEN 10000-terms_bps ELSE 10000 END * fx_num AS n, 10000 * fx_den AS d FROM amounts) SELECT COALESCE(SUM(CAST((2*n+d)/(2*d) AS INTEGER)),0) AS usd_cents FROM final_num WHERE d > 0\"}}"}}
